{"output":"import { useState } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';
import { Card } from './components/ui/card';

export default function App() {
  const [selectedSegment, setSelectedSegment] = useState<string | null>(null);
  
  const data = [
    { name: 'Red', value: 450, color: '#ef4444', gradient: 'from-red-400 to-red-600' },
    { name: 'Blue', value: 550, color: '#3b82f6', gradient: 'from-blue-400 to-blue-600' }
  ];

  const total = data.reduce((sum, item) => sum + item.value, 0);

  const handleSegmentClick = (name: string) => {
    setSelectedSegment(selectedSegment === name ? null : name);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-100 via-emerald-50 to-teal-100 p-8">
      <div className="max-w-5xl mx-auto">
        <div className="text-center mb-12">
          <h1 className="bg-gradient-to-r from-emerald-600 to-teal-600 bg-clip-text text-transparent">
            Interactive Pie Chart
          </h1>
          <p className="text-slate-600 mt-2">Click to explore the data</p>
        </div>
        
        {/* Merged Chart and Cards */}
        <Card className="relative overflow-hidden shadow-2xl bg-white/90 backdrop-blur-sm">
          {/* Gradient background accent */}
          <div className="absolute inset-0 bg-gradient-to-br from-emerald-100/30 to-teal-100/30" />
          
          <div className="relative p-8">
            <div className="grid md:grid-cols-[1fr_1.2fr] gap-8 items-center">
              {/* Pie Chart Section */}
              <div className="flex justify-center">
                <div className="relative">
                  {/* Glow effect behind chart */}
                  <div className="absolute inset-0 bg-gradient-to-r from-red-300/30 to-blue-300/30 blur-3xl rounded-full" />
                  
                  <ResponsiveContainer width={320} height={320}>
                    <PieChart>
                      <defs>
                        <linearGradient id="redGradient" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor="#f87171" />
                          <stop offset="100%" stopColor="#dc2626" />
                        </linearGradient>
                        <linearGradient id="blueGradient" x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor="#60a5fa" />
                          <stop offset="100%" stopColor="#2563eb" />
                        </linearGradient>
                        <filter id="shadow">
                          <feDropShadow dx="0" dy="4" stdDeviation="6" floodOpacity="0.3"/>
                        </filter>
                      </defs>
                      <Pie
                        data={data}
                        cx="50%"
                        cy="50%"
                        innerRadius={70}
                        outerRadius={120}
                        paddingAngle={5}
                        dataKey="value"
                        onClick={(entry) => handleSegmentClick(entry.name)}
                        style={{ cursor: 'pointer', filter: 'url(#shadow)' }}
                      >
                        {data.map((entry) => (
                          <Cell
                            key={entry.name}
                            fill={entry.name === 'Red' ? 'url(#redGradient)' : 'url(#blueGradient)'}
                            opacity={selectedSegment === null || selectedSegment === entry.name ? 1 : 0.3}
                            stroke={selectedSegment === entry.name ? '#fff' : 'none'}
                            strokeWidth={selectedSegment === entry.name ? 4 : 0}
                          />
                        ))}
                      </Pie>
                    </PieChart>
                  </ResponsiveContainer>
                  
                  {/* Center total */}
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                    <div className="text-center">
                      <p className="text-slate-500 text-sm">Total</p>
                      <p className="bg-gradient-to-r from-slate-700 to-slate-900 bg-clip-text text-transparent">{total}</p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Stats Cards Section */}
              <div className="space-y-4">
                {data.map((item) => {
                  const percentage = ((item.value / total) * 100).toFixed(1);
                  const isSelected = selectedSegment === item.name;
                  const isOtherSelected = selectedSegment !== null && !isSelected;

                  return (
                    <div
                      key={item.name}
                      className={`relative overflow-hidden cursor-pointer transition-all duration-300 rounded-xl ${
                        isSelected 
                          ? 'scale-105 shadow-xl' 
                          : isOtherSelected 
                          ? 'opacity-40 scale-95 shadow-sm' 
                          : 'shadow-lg hover:shadow-xl hover:scale-102'
                      }`}
                      onClick={() => handleSegmentClick(item.name)}
                    >
                      {/* Gradient background */}
                      <div className={`absolute inset-0 bg-gradient-to-br ${item.gradient} opacity-10`} />
                      
                      {/* Animated border glow when selected */}
                      {isSelected && (
                        <div className={`absolute inset-0 bg-gradient-to-r ${item.gradient} opacity-20 animate-pulse`} />
                      )}
                      
                      <div className="relative p-5 bg-white/80 backdrop-blur-sm">
                        <div className="flex items-center justify-between">
                          <div className="flex-1">
                            <h3 className="text-slate-700 mb-3">{item.name}</h3>
                            <div className="flex items-end gap-6">
                              <div>
                                <p className="text-slate-500 text-sm mb-1">Number</p>
                                <div className={`bg-gradient-to-r ${item.gradient} bg-clip-text text-transparent`}>
                                  {item.value}
                                </div>
                              </div>
                              <div>
                                <p className="text-slate-500 text-sm mb-1">Percentage</p>
                                <div className={`bg-gradient-to-r ${item.gradient} bg-clip-text text-transparent`}>
                                  {percentage}%
                                </div>
                              </div>
                            </div>
                          </div>
                          
                          {/* Icon with gradient and shadow */}
                          <div className="relative ml-4">
                            <div className={`absolute inset-0 bg-gradient-to-br ${item.gradient} blur-xl opacity-50`} />
                            <div 
                              className={`relative w-16 h-16 rounded-xl flex items-center justify-center bg-gradient-to-br ${item.gradient} shadow-lg transform transition-transform ${
                                isSelected ? 'rotate-12 scale-110' : ''
                              }`}
                            >
                              <span className="text-white text-sm">{percentage}%</span>
                            </div>
                          </div>
                        </div>
                        
                        {/* Bottom gradient accent */}
                        <div className={`absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r ${item.gradient}`} />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="mt-8 text-center">
              <p className="text-slate-500 text-sm">Click on the chart segments or cards to highlight</p>
            </div>
          </div>
        </Card>
      </div>
    </div>
  );
}
