{"output":"import { useEffect, useMemo, useState } from 'react';
import { ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { analyticsApi, analyticsSummaryApi, analyticsStatusApi } from '../services/analyticsApi';

interface RawDataPage {
  columns: string[];
  rows: any[];
  page: number;
  pageSize: number;
  totalRecords: number;
  totalPages: number;
}

function toIso(d: Date) { return d.toISOString().slice(0, 10); }

export function SalesOrderAnalysis() {
  const [dateStart, setDateStart] = useState<string>(''); // yyyy-mm-dd
  const [dateEnd, setDateEnd] = useState<string>(''); // yyyy-mm-dd
  const [data, setData] = useState<RawDataPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(1);
  const [summary, setSummary] = useState<{ totalRecords: number; totalRevenue?: number; totalQuantity?: number } | null>(null);
  const [statusBreakdown, setStatusBreakdown] = useState<{ saled: number; cancel: number; total: number }>({ saled: 0, cancel: 0, total: 0 });
  const [statusFilter, setStatusFilter] = useState<string | undefined>(undefined);

  useEffect(() => {
    let ignore = false;
    async function load() {
      setLoading(true);
      setError(null);
      try {
        const [res, sum, st] = await Promise.all([
          analyticsApi.rawOrders({
            page,
            pageSize: 50,
            dateStart: dateStart || undefined,
            dateEnd: dateEnd || undefined,
            status: statusFilter || undefined
          }),
          analyticsSummaryApi.rawSummary({ dateStart: dateStart || undefined, dateEnd: dateEnd || undefined }),
          analyticsStatusApi.rawStatus({ dateStart: dateStart || undefined, dateEnd: dateEnd || undefined })
        ]);
        if (!ignore) setData(res.data.data);
        if (!ignore) setSummary(sum.data.data);
        if (!ignore) {
          const rows = st.data.data.rows || [];
          const total = st.data.data.total || 0;
          const saled = rows.filter((r) => String(r.status).toLowerCase() === 'saled').reduce((a, b) => a + b.count, 0);
          const cancel = rows.filter((r) => String(r.status).toLowerCase() === 'cancel').reduce((a, b) => a + b.count, 0);
          setStatusBreakdown({ saled, cancel, total });
        }
      } catch (e) {
        if (!ignore) {
          const anyErr = e as any;
          const serverMsg = anyErr?.response?.data?.error;
          const msg = typeof serverMsg === 'string' ? serverMsg : (e instanceof Error ? e.message : 'Failed to load');
          setError(msg);
        }
      } finally {
        if (!ignore) setLoading(false);
      }
    }
    load();
    return () => {
      ignore = true;
    };
  }, [page, dateStart, dateEnd, statusFilter]);

  function setDaily() {
    const d = new Date();
    const yesterday = new Date(d);
    yesterday.setDate(d.getDate() - 1);
    setDateStart(toIso(yesterday));
    setDateEnd(toIso(d));
    setPage(1);
  }

  function setYTD() {
    const d = new Date();
    const start = new Date(d.getFullYear(), 0, 1);
    setDateStart(toIso(start));
    setDateEnd(toIso(d));
    setPage(1);
  }

  function clearDates() {
    setDateStart('');
    setDateEnd('');
    setStatusFilter(undefined);
    setPage(1);
  }

  const fromIdx = useMemo(() => (data ? (data.page - 1) * data.pageSize + 1 : 0), [data]);
  const toIdx = useMemo(
    () => (data ? Math.min(data.page * data.pageSize, data.totalRecords) : 0),
    [data]
  );

  function downloadBlob(content: BlobPart, fileName: string, contentType: string) {
    const blob = new Blob([content], { type: contentType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  async function exportAllToExcel() {
    // Export all filtered rows (not just current page)
    // Use max pageSize 500 for fewer requests
    const pageSize = 500;
    const start = dateStart || undefined;
    const end = dateEnd || undefined;

    // Ensure we have columns and total count
    let columns = data?.columns ?? [] as string[];
    let totalRecords = summary?.totalRecords;
    if (!totalRecords || totalRecords < 0) {
      try {
        const s = await analyticsSummaryApi.rawSummary({ dateStart: start, dateEnd: end });
        totalRecords = s.data.data.totalRecords;
      } catch {
        // fallback to at least current page
        totalRecords = data?.totalRecords ?? 0;
      }
    }

    if (!columns.length) {
      // fetch a small page to get columns
      const one = await analyticsApi.rawOrders({ page: 1, pageSize: 1, dateStart: start, dateEnd: end });
      columns = one.data.data.columns;
    }

    const totalPages = Math.max(Math.ceil((totalRecords ?? 0) / pageSize), 1);
    const header = columns.join(',');
    const allRows: string[] = [];

    for (let p = 1; p <= totalPages; p++) {
      // eslint-disable-next-line no-await-in-loop
      const res = await analyticsApi.rawOrders({ page: p, pageSize, dateStart: start, dateEnd: end });
      const rows = res.data.data.rows.map((row) =>
        columns
          .map((c) => {
            const v = row[c];
            if (v === null || v === undefined) return '';
            const s = String(v);
            return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
          })
          .join(',')
      );
      allRows.push(...rows);
    }

    const csv = [header, ...allRows].join('\n');
    const fnameStart = dateStart || 'all';
    const fnameEnd = dateEnd || 'all';
    const file = `sale_order_lines_${fnameStart}_to_${fnameEnd}_all.csv`;
    downloadBlob(csv, file, 'text/csv;charset=utf-8;');
  }

  return (
    <div className="flex flex-col gap-6" data-testid="sales-order-analysis">
